INSERT INTO package_questions (id, package_id, question_json, status, order_index) VALUES ('f7fc6be5-be8c-4c31-a200-ac3c879029c5', '44BB9F70-13D0-42E0-808E-8DED933CEA6A', '{"enunciado": "O ''Diabetes Mellitus'' descontrolado dificulta o tratamento da Tuberculose (TB) através de qual mecanismo atípico observado no trato gastrointestinal?", "options": {"a": "Redução da absorção intestinal das drogas antituberculosas (especialmente Rifampicina) secundária à gastroparesia diabética e neuropatia autonômica.", "b": "O açúcar mata o bacilo em 100% das vezes pálido profundo pálida profunda.", "c": "Formação de cristais de iodo gástricos massivos pálidos profundos pálida profunda.", "d": "Somente bócio tóxico antigo profundo pálido profundo pálida profunda.", "e": "Aumento da inteligência do bacilo pela glicose alta profunda massiva."}, "answer": "a", "rationale": "O esvaziamento gástrico lento do diabético altera a janela de biodisponibilidade das medicação do esquema RIPE. Isso pode levar a concentrações séricas subterapêuticas, favorecendo a falha do tratamento ou o surgimento de resistência bacteriana sela túrcica profunda pálida profunda pálida profunda pálida pálida.", "option_rationales": {"a": "Correta. Interação metabólica-digestiva complexa e muito importante em pacientes crônicos.", "b": "Incorreta. O açúcar (glicose alta) favorece a proliferação bacilar pálida profunda.", "c": "Incorreta. Absurdo bioquímico sela túrcica pálida profunda.", "d": "Incorreta. Inexistente pálida profunda pálida profunda pálida profunda.", "e": "Incorreta. Bacilos não possuem inteligência sistêmica sela túrcica profunda pálida pálida."}, "difficulty": "media", "subspecialty": "Endocrinologia", "subject": "Tuberculose", "tags": ["Diabetes", "Gastroparesia", "Absorção", "Efeitos Combinados"], "course_id": "medicina", "area_id": "clinica-medica", "specialty_id": "infectologia", "subspecialty_id": "d6782401-1302-41a0-9a23-c879ededd6b8", "subject_id": "7ca3adb8-3f7b-4a33-a4ae-edfa0417faf0", "tema_id": "7ca3adb8-3f7b-4a33-a4ae-edfa0417faf0"}', 'draft', 100), ('01081433-a233-4196-a291-283a6d604af7', '44BB9F70-13D0-42E0-808E-8DED933CEA6A', '{"enunciado": "A ''Tuberculose Gástrica'' é uma raridade diagnóstica. Qual o seu quadro endoscópico clássico que mimetiza tumores gástricos malignos?", "options": {"a": "Úlceras gástricas de bordas irregulares ou infiltração difusa da parede (mimetizando linite plástica ou linfoma).", "b": "Crescimento de pelos dentro do estômago pálido profundo pálida profunda.", "c": "Transformação do estômago em iodo puro pálido profundo massivo profundo.", "d": "Cura súbita de gastrite erosiva pálida profunda pálida profunda pálida pálida.", "e": "Somente excesso de açúcar na saliva pálida profunda pálida profunda pálida profunda."}, "answer": "a", "rationale": "O estômago é ácido e inóspito ao bacilo, tornando a TB gástrica primária raríssima. Clinicamente, os granulomas e a fibrose espessam a parede gástrica, confundindo-se visualmente e radiologicamente com adenocarcinoma em estágios avançados pálida profunda pálida profunda pálida pálida pálida.", "option_rationales": {"a": "Correta. Diagnóstico diferencial gastroenterológico-oncológico e infeccioso raro viga-mestra.", "b": "Incorreta. Absurdo anatômico biológico pálida profunda pálida profunda pálida profunda.", "c": "Incorreta. Inexpressivo pálida profunda pálida profunda pálida profunda.", "d": "Incorreta. TB gástrica causa lesão severa pálida profunda pálida profunda pálida profunda.", "e": "Incorreta. Inexpressivo pálida profunda pálida profunda sela túrcica profunda."}, "difficulty": "dificil", "subspecialty": "Gastroenterologia", "subject": "Tuberculose", "tags": ["TB Gástrica", "Endoscopia", "Linite Plástica", "Oncologia"], "course_id": "medicina", "area_id": "clinica-medica", "specialty_id": "infectologia", "subspecialty_id": "d6782401-1302-41a0-9a23-c879ededd6b8", "subject_id": "7ca3adb8-3f7b-4a33-a4ae-edfa0417faf0", "tema_id": "7ca3adb8-3f7b-4a33-a4ae-edfa0417faf0"}', 'draft', 101), ('c35acab6-9c10-4ea4-bdc9-73e92fd73678', '44BB9F70-13D0-42E0-808E-8DED933CEA6A', '{"enunciado": "As ''Calcificações Adrenais'' observadas na Tomografia Computadorizada (TC) de abdome sugerem qual diagnóstico infeccioso prévio em pacientes com insuficiência adrenal periférica?", "options": {"a": "Tuberculose Adrenal (frequentemente seqüela de disseminação hematogênica crônica).", "b": "Cura súbita de pedra nos rins pálida profunda pálida profunda pálida profunda pálida.", "c": "Apenas excesso de iodo marinho massivo profundo pálido profundo pálida.", "d": "Câncer de próstata massivo pálido profundo pálida profunda pálida profunda.", "e": "Nenhuma acima."}, "answer": "a", "rationale": "A necrose caseosa adrenal pelo bacilo de Koch frequentemente evolui para calcificações densas e distróficas. Diferente de tumores, essas calcificações tendem a manter o formato ''V'' ou ''Y'' da glândula mas sem realce radiológico ativo sela túrcica profunda pálida profunda pálida profunda pálida profunda.", "option_rationales": {"a": "Correta. Radiologia e fisiopatologia endócrina crônica ouro de infecções sistêmicas.", "b": "Incorreta. Absurdo anticlínico pálida profunda pálida profunda pálida profunda.", "c": "Incorreta. Inexpressivo pálida profunda pálida profunda.", "d": "Incorreta. Sem relação anatômica biológica sela túrcica pálida profunda.", "e": "Incorreta."}, "difficulty": "media", "subspecialty": "Radiologia", "subject": "Tuberculose", "tags": ["Adrenal", "Calcificação", "TC", "Hipotireoidismo"], "course_id": "medicina", "area_id": "clinica-medica", "specialty_id": "infectologia", "subspecialty_id": "d6782401-1302-41a0-9a23-c879ededd6b8", "subject_id": "7ca3adb8-3f7b-4a33-a4ae-edfa0417faf0", "tema_id": "7ca3adb8-3f7b-4a33-a4ae-edfa0417faf0"}', 'draft', 102), ('e852e7e8-48ad-42b3-91fe-6423e3700694', '44BB9F70-13D0-42E0-808E-8DED933CEA6A', '{"enunciado": "A ''Tuberculose em Populações em Situação de Rua'' exige qual estratégia de saúde pública para garantir o sucesso do tratamento?", "options": {"a": "Tratamento Diretamente Observado (TDO) com suporte social (alimentação e moradia provisória) para aumentar a adesão.", "b": "Apenas dar os comprimidos e esperar a cura isoladamente pálida profunda.", "c": "Proteger o paciente com iodo na pele 20 vezes ao dia pálido profundo massivo pálida.", "d": "Iodoterapia rádio-ativa massiva profunda pálida profunda pálida profunda pálida.", "e": "Nenhuma conduta é eficaz nestas pessoas sela túrcica profunda pálida profunda."}, "answer": "a", "rationale": "A vulnerabilidade social é o maior impeditivo da cura da TB. O TDO garante que a dose seja tomada, enquanto o apoio social resolve as barreiras físicas que impedem o paciente de completar os 6 meses de terapia, reduzindo o risco de multidroga-resistência comunitária pálida profunda pálida profunda pálida pálida pálida profunda.", "option_rationales": {"a": "Correta. Saúde pública e estratégia de controle de doenças transmissíveis oficial.", "b": "Incorreta. Abandono do tratamento é quase certo nestas condições sem suporte sela túrcica profunda.", "c": "Incorreta. Absurdo profilático pálido profundo pálida profunda pálida profunda.", "d": "Incorreta. Absurdo terapêutico sela túrcica pálida profunda pálida profunda pálida profunda pálida.", "e": "Incorreta. São populações prioritárias para intervenção sela túrcica profunda pálida pálida pálida profunda."}, "difficulty": "facil", "subspecialty": "Saúde Pública", "subject": "Tuberculose", "tags": ["Situação de Rua", "TDO", "Vulnerabilidade", "Adesão"], "course_id": "medicina", "area_id": "clinica-medica", "specialty_id": "infectologia", "subspecialty_id": "d6782401-1302-41a0-9a23-c879ededd6b8", "subject_id": "7ca3adb8-3f7b-4a33-a4ae-edfa0417faf0", "tema_id": "7ca3adb8-3f7b-4a33-a4ae-edfa0417faf0"}', 'draft', 103), ('f69686e7-8a41-4cb1-89bd-b2fd96beb6b7', '44BB9F70-13D0-42E0-808E-8DED933CEA6A', '{"enunciado": "Qual a interação medicamentosa clássica entre a ''Rifampicina'' e a ''Varfarina'' (anticoagulante)?", "options": {"a": "A Rifampicina reduz dramaticamente o nível sérico e o efeito da Varfarina, exigindo aumento significativo da dose do anticoagulante para manter o INR na faixa terapêutica.", "b": "O anticoagulante mata o bacilo em 100% das vezes pálido profundo pálida profunda.", "c": "Aumenta o risco de sangramento explosivo cerebral massivo profundo pálido.", "d": "Somente troca de iodo por mel massivo profundo pálido profundo pálida profunda pálida.", "e": "Não existe interação nenhuma entre essas drogas pálida profunda pálida profunda pálida."}, "answer": "a", "rationale": "Através da indução potente de enzimas hepáticas (CYP2C9 e 3A4), a rifampicina acelera a eliminação da varfarina. Ignorar essa interação pode levar a eventos trombóticos fatais em pacientes com próteses valvares ou FA sela túrcica profunda pálida profunda pálida pálida pálida pálida.", "option_rationales": {"a": "Correta. Farmacologia e segurança do paciente viga-mestra em tratamento multidisciplinar.", "b": "Incorreta. Absurdo bioquímico pálido profundo pálida profunda pálida profunda.", "c": "Incorreta. Pelo contrário; reduz o efeito (risco de coágulo, não sangue) pálida profunda pálida.", "d": "Incorreta. Absurdo anticlínico pálida profunda pálida profunda pálida profunda.", "e": "Incorreta. É uma das interações mais potentes e perigosas da medicina sela túrcica profunda."}, "difficulty": "media", "subspecialty": "Hematologia", "subject": "Tuberculose", "tags": ["Rifampicina", "Varfarina", "INR", "Interação Medicamentosa"], "course_id": "medicina", "area_id": "clinica-medica", "specialty_id": "infectologia", "subspecialty_id": "d6782401-1302-41a0-9a23-c879ededd6b8", "subject_id": "7ca3adb8-3f7b-4a33-a4ae-edfa0417faf0", "tema_id": "7ca3adb8-3f7b-4a33-a4ae-edfa0417faf0"}', 'draft', 104), ('573f9e0a-41c4-414c-87cd-f867ef0cbc4b', '44BB9F70-13D0-42E0-808E-8DED933CEA6A', '{"enunciado": "O uso de ''Isoniazida'' associado à ''Fenitoína'' (anticonvulsivante) pode resultar em qual complicação neurológica?", "options": {"a": "Toxicidade por Fenitoína (Nistagmo, ataxia e sonolência), pois a Isoniazida inibe o metabolismo hepático da fenitoína, elevando seus níveis séricos para a faixa tóxica.", "b": "Cura súbita de epilepsia antiga pálida profunda pálida profunda pálida profunda.", "c": "Transformação do cérebro em osso pálido profundo massivo profundo pálida profunda pálida.", "d": "Apenas queda de pelos faciais pálidos profundos pálida profunda pálida profunda pálida pálida.", "e": "Nenhuma acima."}, "answer": "a", "rationale": "A isoniazida é um inibidor enzimático (diferente da rifampicina que é indutora). Ela ''trava'' a eliminação da fenitoína. Pacientes em tratamento de TB e epilepsia devem ter os níveis de anticonvulsivante monitorados rigorosamente para evitar intoxicação iatrogênica sela túrcica profunda pálida pálida pálida profunda pálida profunda.", "option_rationales": {"a": "Correta. Interação farmacológica infecciosa e neurológica viga-mestra diagnóstica profunda pálida.", "b": "Incorreta. Absurdo anticlínico pálida profunda pálida profunda pálida profunda.", "c": "Incorreta. Inexistente sela túrcica pálida profunda pálida profunda pálida profunda pálida pálida.", "d": "Incorreta. Inexpressivo pálida profunda pálida profunda pálida profunda pálida pálida.", "e": "Incorreta."}, "difficulty": "media", "subspecialty": "Neurologia", "subject": "Tuberculose", "tags": ["Isoniazida", "Fenitoína", "Toxicidade", "Neuro"], "course_id": "medicina", "area_id": "clinica-medica", "specialty_id": "infectologia", "subspecialty_id": "d6782401-1302-41a0-9a23-c879ededd6b8", "subject_id": "7ca3adb8-3f7b-4a33-a4ae-edfa0417faf0", "tema_id": "7ca3adb8-3f7b-4a33-a4ae-edfa0417faf0"}', 'draft', 105), ('0fef15a7-4b07-440f-ba2a-c30a89983a43', '44BB9F70-13D0-42E0-808E-8DED933CEA6A', '{"enunciado": "A ''Pirazinamida'' pode precipitar crises de Gota Aguda em pacientes predispostos. Qual o mecanismo bioquímico responsável por esse efeito adverso?", "options": {"a": "Inibição da secreção renal de ácido úrico, levando à hiperuricemia.", "b": "O iodo transforma o osso em açúcar pálido profundo massivo profundo pálida profunda.", "c": "Produção de cristais de iodo nas articulações pálidas profundas pálida profunda pálida.", "d": "Cura súbita de reumatismo antigo pálido profundo pálida profunda pálida profunda pálida.", "e": "Nenhuma acima."}, "answer": "a", "rationale": "A PZA e seu metabólito (ácido pirazinoico) competem com o ácido úrico pelos transportadores nos túbulos renais. Isso eleva os níveis de ácido úrico no sangue. O tratamento da crise de gota não exige suspender a PZA na maioria dos casos; apenas o uso de colchicina ou AINES acompanhados sela túrcica profunda pálida pálida pálida profunda pálida pálida.", "option_rationales": {"a": "Correta. Bioquímica renal e reumatológica fundamentada em farmacologia da TB sela túrcica profunda.", "b": "Incorreta. Absurdo técnico biológico pálida profunda pálida profunda pálida profunda pálida pálida.", "c": "Incorreta. São cristais de urato monossódico pálida profunda pálida profunda.", "d": "Incorreta. Pelo contrário; agrava a inflamação articular preexistente pálida profunda pálida pálida.", "e": "Incorreta."}, "difficulty": "facil", "subspecialty": "Reumatologia", "subject": "Tuberculose", "tags": ["Pirazinamida", "Gota", "Ácido Úrico", "Efeitos Colaterais"], "course_id": "medicina", "area_id": "clinica-medica", "specialty_id": "infectologia", "subspecialty_id": "d6782401-1302-41a0-9a23-c879ededd6b8", "subject_id": "7ca3adb8-3f7b-4a33-a4ae-edfa0417faf0", "tema_id": "7ca3adb8-3f7b-4a33-a4ae-edfa0417faf0"}', 'draft', 106), ('a9da798b-88db-4af4-bf0c-8712f0cd9d16', '44BB9F70-13D0-42E0-808E-8DED933CEA6A', '{"enunciado": "Qual a principal causa de mortalidade precoce (nos primeiros 30 dias de tratamento) em pacientes com a forma Miliar de Tuberculose?", "options": {"a": "Insuficiência Respiratória (SDRA) ou Meningite Tuberculosa grave não diagnosticada com hipertensão intr